B=[
dict(a=1,z=5,star=2,lit=L(1,5),
key=[('毀滅','H7843','mashkhit','毀滅、毀壞'),('簸揚','H2219','zeruha','簸揚、分散'),('外邦人','H2114','zarim','外邦人、陌生人'),('憐惜','H2550','takhmelu','憐惜'),('滅盡','H2763','kharimu','滅盡、獻為當毀滅的'),('丟棄','H488','alman','被撇下如寡婦'),('罪','H817','asham','罪過、罪責')],
gram=['**立加米**：原文 lev qamai，字面是「起來攻擊我的人的心」，多數解經者認為是一種字母替換的暗號（亞特巴施密碼），指「迦勒底」。經文不說破，我們也不把它讀成別的地方。','**沒有被丟棄**：原文用「寡婦」（almon）的字根，意思是：他們雖然像是被撇下，卻沒有成為寡婦，因為丈夫沒有離開。'],
exp=['五十一章，接續五十章，是耶利米書論巴比倫的下篇，也是全書最長的一個預言之一。一節說：我必使毀滅的風颳起，攻擊巴比倫和住在立加米的人。這個「立加米」，是一個看起來有些奇怪的地名；多數解經者認為，它是一種文字的暗號，指的是迦勒底。經文自己不解釋，我們也不多說。','二節說：我要打發外邦人來到巴比倫，簸揚她，使她的地空虛。簸揚，是農夫在打穀場上，用風把穀殼吹走的動作。這是一個很具體的畫面：風來了，吹走的是空殼。三、四節說到攻擊的場景：不要憐惜她的少年人；他們必在迦勒底人之地被殺仆倒。這些話很重。我們誠實地說：這是對那個時代巴比倫的預言，不是今日信徒的指令；我們也不替它加上日期。','然後，是五節，一句很溫柔的轉折：以色列和猶大雖然境內充滿違背以色列聖者的罪，卻沒有被他的神萬軍之耶和華丟棄。這一節和五十章相互呼應：神的百姓有罪，這是事實；可是，他們沒有被丟棄，也是事實。罪，和被丟棄，不是同一件事。我們讀這一節，要看見的重點是：神的信實，不是建立在我們的完美上。']),
dict(a=6,z=10,star=3,lit=L(6,10),
key=[('逃奔','H5127','nusu','逃跑、逃奔'),('罪孽','H5771','avon','罪孽'),('報應','H1576','gemul','報應、回報'),('金杯','H3563','kos zahav','金杯'),('顛狂','H1984','yithollelu','顛狂、發狂'),('乳香','H6875','tseri','乳香（藥膏）'),('公義','H6666','tsidqotenu','我們的公義')],
gram=['**各救自己的性命**：這是一個清楚的命令：逃，各人，救自己的性命。','**公義**：十節的「彰顯我們的公義」，原文是複數：神的作為，是祂百姓的「公義的事」，意思是：神為他們伸冤，證明他們的清白。'],
exp=['六節是一道很急迫的呼召：你們要從巴比倫中逃奔，各救自己的性命！不要陷在她的罪孽中一同滅亡；因為這是耶和華報仇的時候。請你留意，「逃」，在這裡不是懦弱，是神的命令。有時候，最屬靈的行動，就是離開。','七節，用了一個很有力的比喻：巴比倫素來是耶和華手中的金杯，使天下沉醉；萬國喝了她的酒就顛狂了。金杯，是華美的，也是神手中的器皿。意思是：連巴比倫的興起，也在神的手中；可是，這個金杯，使天下沉醉，所以，它要被打破。八、九節，是一種很沉重的哀歌：巴比倫忽然傾覆毀壞；要為她哀號；拿乳香或者可以治好。我們想醫治巴比倫，她卻沒有治好。離開她吧！','請你注意：這裡，沒有幸災樂禍。有人哀號，有人想醫治，最後，是離開。十節說：耶和華已經彰顯我們的公義。來吧！我們可以在錫安報告耶和華我們神的作為。這個「報告」，不是對仇敵的炫耀，而是在敬拜的地方，說出神做了什麼。我們不為這幾節，加上日期，也不套用到今日任何地方。']),
dict(a=11,z=14,star=2,lit=L(11,14),
key=[('米底亞','H4074','madai','米底亞'),('報仇','H5360','niqmat','報仇'),('殿','H1964','heikhalo','殿'),('結局','H7093','qetsekh','結局、終點'),('貪婪','H1215','betsekh','貪婪、不義之利'),('起誓','H7650','nishba','起誓'),('螞蚱','H3218','yeleq','螞蚱、蝗蟲')],
gram=['**貪婪之量滿了**：原文是「你利得的尺寸（betsa）到了」，意思是：不義之財，到了該被量盡的時候。','**像螞蚱一樣**：螞蚱，是一個多得數不清的比喻；「敵人充滿你，像螞蚱」，意思是：無處躲藏。'],
exp=['十一節，是一連串戰爭的命令：你們要磨尖了箭頭，抓住盾牌。神定意攻擊巴比倫，所以激動了米底亞君王的心。這裡，審判的工具，是米底亞君王；可是，推動的，是神。我們不為這一句，加上日期，也不把「米底亞」套用到今日任何地方。','十一節也說：這是耶和華報仇，就是為自己的殿報仇。這句話，和五十章二十八節呼應。神的殿，被毀壞，神說：這是我的殿。報仇，是神的事，是為祂的名、祂的殿，不是人對人的私仇。十二節，說到瞭望臺與守望的人，設下埋伏；意思是：這一切，神已經作成。','十三節，是一個很重的稱呼：住在眾水之上多有財寶的啊，你的結局到了！你貪婪之量滿了！巴比倫，坐落在大河與水道之上，財寶豐富。可是，神說：你的結局到了。「貪婪之量滿了」，是一個很有畫面的說法：不義之財，有一個盛量，滿了，就倒出來。十四節，神指著自己起誓，要使敵人充滿她，像螞蚱一樣。']),
dict(a=15,z=19,star=3,lit=L(15,19),
key=[('能力','H3581','koakh','能力、權能'),('智慧','H2451','khokhmah','智慧'),('聰明','H8394','tevunah','聰明、悟性'),('偶像','H6459','pesel','雕刻的偶像'),('虛假','H8267','sheqer','虛假、謊言'),('虛無','H1892','hevel','虛無、氣息'),('造作','H3335','yotser','造作者、製陶者')],
gram=['**虛無**：原文 hevel，就是傳道書的「虛空」，字面是「氣息、一口氣」，意思是：一口氣就吹散的東西。','**造作萬有的主**：yotser，是「製陶者」，也是「造型者」；耶利米書十八章的陶匠，用的是同一個字根。'],
exp=['十五節到十九節，是一首插在審判裡的頌歌：耶和華用能力創造大地，用智慧建立世界，用聰明鋪張穹蒼。十六節說：他一發聲，空中便有多水激動；他使雲霧從地極上騰。這段話，和十章十二到十六節幾乎完全相同。這是耶利米書裡，少數重複出現的段落，是整卷書的信仰核心：創造者，是真神。','十七、十八節，是對偶像的對比：各人都成了畜類，毫無知識。各銀匠都因他的偶像羞愧；他所鑄的偶像本是虛假的，其中並無氣息。都是虛無的，是迷惑人的工作。這是一個很簡單的對照：創造者有能力，偶像沒有氣息。','然後，十九節，是整段的結論：雅各的分不像這些，因他是造作萬有的主；以色列也是他產業的支派。萬軍之耶和華是他的名。請你想想：在一章充滿審判的預言中間，神讓祂的百姓，聽見這首頌歌。因為，人所倚靠的，如果是虛無，就會一起消失；人所倚靠的，如果是創造者，就不會。']),
dict(a=20,z=23,star=2,lit=L(20,23),
key=[('斧子','H4661','mappets','斧子、大錘'),('兵器','H3627','keli','器具、兵器'),('打碎','H5310','nipatsti','打碎、粉碎'),('戰車','H7393','rekhev','戰車'),('老年人','H2205','zaqen','老年人'),('牧人','H7462','roeh','牧人'),('省長','H6346','pakhot','省長')],
gram=['**打碎**：二十至二十三節，這個動詞連續重複了十二次，是整章最有節奏的一段。','**你是我爭戰的斧子**：「你」，指的是被神使用的那個力量；有人認為是巴比倫自己，有人認為是神所用的另一個工具，經文沒有指明，我們不下定論。'],
exp=['二十節到二十三節，是一個很有節奏的段落：「用你打碎」，連續重複了十二次。你是我爭戰的斧子和打仗的兵器；我要用你打碎列國，用你毀滅列邦；用你打碎馬和騎馬的；打碎戰車和坐在其上的；打碎男人和女人；打碎老年人和少年人；打碎壯丁和處女；打碎牧人和他的群畜；打碎農夫和他一對牛；打碎省長和副省長。','這一段很重，也很特別。這個「你」，是誰？有人認為，是巴比倫自己，曾經被神使用，作為打碎列國的斧子；有人認為，是神另外所用的力量。經文沒有說明，我們不替它補上答案。我們可以確定的是：這一段，用的是神的口吻，描寫一個力量被神使用的畫面。','這一段，也不是對今日信徒的指令。它的重複，是為了讓聽的人，感受到那種全面性：所有的人、所有的行業、所有的階層，都在其中。我們讀這一段，最重要的提醒是：沒有一個人，包括強大的帝國，可以在神的手之外。我們也不把它套用到今日任何地方。']),
dict(a=24,z=26,star=2,lit=L(24,26),
key=[('報復','H7999','shillamti','報復、償還'),('錫安','H6726','tsiyyon','錫安'),('行毀滅','H4889','hammashkhit','毀滅者、行毀滅的'),('滾下去','H1556','vegilgaltikha','使滾下去'),('燒毀','H8316','serefah','燒毀'),('房角石','H6438','pinnah','房角石'),('荒涼','H8077','shemamot','荒涼')],
gram=['**我必在你們眼前報復**：「報復」，原文 shillamti，字根是「償還、使完整」，意思是：把應有的歸還。','**燒毀的山**：二十五節的「山」，有人認為是比喻巴比倫這個強權，不是一座真的山。'],
exp=['二十四節，神說：我必在你們眼前報復巴比倫人和迦勒底居民在錫安所行的諸惡。請你留意：「在錫安所行的諸惡」，是整個預言的理由。神不是任意的審判，而是回應那些，在祂的城裡所行的惡。這個「報復」，字面是「償還」，意思是：該還的，神要還。','二十五節，神稱巴比倫為一座山：你這行毀滅的山哪，就是毀滅天下的山，我與你反對。我必向你伸手，將你從山巖滾下去，使你成為燒毀的山。這是一個很有畫面的比喻：一座曾經高聳的山，被滾下去，被燒毀。有人認為，這個「山」，是比喻巴比倫這個強權。我們不確定，也不需要多說。','二十六節，是一句很沉重的話：人必不從你那裡取石頭為房角石，也不取石頭為根基石；你必永遠荒涼。房角石與根基石，是建築最基本的石頭。連這樣的石頭，也沒有人要取，意思是：這座山，再也不能成為任何建築的根基。我們不為這幾節，加上日期，也不套用到今日任何地方。']),
dict(a=27,z=32,star=2,lit=L(27,32),
key=[('大旗','H5251','nes','旗、旗號'),('吹角','H8628','tiqu shofar','吹號角'),('亞拉臘','H780','ararat','亞拉臘（山地邦國）'),('軍長','H2951','tifsar','軍長'),('勇士','H1368','gibborei','勇士'),('門閂','H1280','beriakheiha','門閂'),('驚慌','H926','nivhalu','驚慌、倉皇')],
gram=['**亞拉臘、米尼、亞實基拿**：這是在巴比倫北方山地的幾個邦國名稱；經文只列名字，我們不把它們套用到今日任何地方。','**跑報的要彼此相遇**：原文是「跑的人迎著跑的人」，描寫消息傳得很快，一個接一個。'],
exp=['二十七節，是一道召集令：要在境內豎立大旗，在各國中吹角，使列國預備攻擊巴比倫，將亞拉臘、米尼、亞實基拿各國招來攻擊她。這些，都是在巴比倫北方山地的邦國名稱。經文只列名字，我們也只讀名字，不替它們補上歷史細節，也不把它們套用到今日任何地方。','二十八節，說：使列國和米底亞君王，與省長和副省長，並他們所管全地之人，都預備攻擊她。二十九節說：地必震動而瘠苦；因耶和華向巴比倫所定的旨意成立了。三十節，是巴比倫的反應：勇士止息爭戰，藏在堅壘之中。他們的勇力衰盡，好像婦女一樣。巴比倫的住處有火著起，門閂都折斷了。','三十一、三十二節，是一個很有畫面的描寫：跑報的要彼此相遇，送信的要互相迎接，報告巴比倫王說：城的四方被攻取了，渡口被佔據了，葦塘被火燒了，兵丁也驚慌了。請你想想：消息一個接一個地傳來，每一個，都比上一個更壞。這是一個很真實的描寫：災難來臨的時候，最難受的，是消息一個接一個地來。']),
dict(a=33,z=37,star=3,lit=L(33,37),
key=[('禾場','H1637','goren','禾場、打穀場'),('收割','H7105','qatsir','收割'),('吞滅','H398','akhalani','吞滅'),('空虛','H7385','reiq','空虛'),('強暴','H2555','khamasi','強暴、暴力'),('伸冤','H7378','riv','伸冤、爭訟'),('亂堆','H1530','gallim','亂堆、石堆')],
gram=['**像大魚將我吞下**：原文 tannin，是巨大的水中生物（可譯作大魚或大蛇）；「吞下」又吐出，與四十四節的彼勒「吐出所吞的」，是同一個畫面。','**伸冤**：原文 riv，是法庭用語，「打官司、爭訟」，與五十章三十四節的「伸清他們的冤」，是同一個字根。'],
exp=['三十三節，用一個農業的比喻：巴比倫城好像踹穀的禾場；再過片時，收割她的時候就到了。禾場，是打穀的地方，穀子被踹，殼被吹走。這個比喻，和二節的「簸揚」，互相呼應。神說：再過片時，收割的時候就到了。','三十四、三十五節，是以色列人與錫安居民的申訴：巴比倫王尼布甲尼撒吞滅我，壓碎我，使我成為空虛的器皿。他像大魚將我吞下，用我的美物充滿他的肚腹，又將我趕出去。巴比倫以強暴待我，損害我的身體，願這罪歸給她。請你留意：這是受害者的聲音，在聖經裡，被保留下來。神沒有說：不要這樣說。神把這些話，記在聖經裡。','然後，三十六節，是神的回答：所以，耶和華如此說：我必為你伸冤，為你報仇；我必使巴比倫的海枯竭，使她的泉源乾涸。這個「伸冤」，是打官司的字：神為你打官司。三十七節，說：巴比倫必成為亂堆，為野狗的住處，令人驚駭、嗤笑，並且無人居住。這裡，有一個很重要的細節：神先聽了受害者的申訴，才說話。我們不為這些話，加上日期，也不套用到今日任何地方。']),
dict(a=38,z=44,star=2,lit=L(38,44),
key=[('獅子','H738','arayot','獅子'),('酒席','H4960','mishtehem','酒席、筵席'),('沉醉','H7937','vehishkarti','使沉醉'),('示沙克','H8347','sheshakh','示沙克（巴比倫的暗號）'),('彼勒','H1078','bel','彼勒（巴比倫的神）'),('吐出','H3318','vehotseti','使出來、吐出'),('沙漠','H6160','aravah','沙漠、荒原')],
gram=['**示沙克**：原文 sheshakh，多數解經者認為也是一種字母替換的暗號（亞特巴施密碼），指「巴比倫」，與一節的「立加米」同類。','**睡了長覺，永不醒起**：這是婉轉的說法，表示死亡；經文用一個宴席的畫面，說出一個結局。'],
exp=['三十八節，用獅子的叫聲，描寫敵人：他們要像少壯獅子咆哮，像小獅子吼叫。三十九節，是一個很特別的畫面：他們火熱的時候，我必為他們設擺酒席，使他們沉醉，好叫他們快樂，睡了長覺，永不醒起。這是一個婉轉的說法：宴席越是熱鬧，結局越是出人意料。四十節，說：我必使他們像羊羔、像公綿羊和公山羊下到宰殺之地。','四十一節，是一句感嘆：示沙克何竟被攻取？天下所稱讚的何竟被佔據？巴比倫在列國中何竟變為荒場？「示沙克」，多數解經者認為是巴比倫的另一個暗號。這個感嘆，是對那個世人眼中最輝煌的城市，倒下的驚訝。四十二、四十三節，描寫海水漲起，漫過巴比倫；她的城邑變為荒場、旱地、沙漠。','四十四節，說：我必刑罰巴比倫的彼勒，使他吐出所吞的。萬民必不再流歸他那裡；巴比倫的城牆也必坍塌了。「吐出所吞的」，是一個很有畫面的比喻：被吞進去的，要被吐出來。這和三十四節的「大魚將我吞下」，互相呼應。神說：被吞下的，要被吐出來。我們不為這些話，加上日期，也不套用到今日任何地方。']),
dict(a=45,z=50,star=3,lit=L(45,50),
key=[('出去','H3318','tseu','出去'),('烈怒','H2740','kharon','烈怒'),('膽怯','H7401','yerakh','軟弱、膽怯'),('風聲','H8052','shemuah','風聲、消息'),('歡呼','H7442','venannu','歡呼'),('記念','H2142','zikhru','記念'),('刀劍','H2719','kherev','刀劍')],
gram=['**我的民哪，你們要從其中出去**：「出去」是命令式，「我的民」是呼召的對象；這一句，在新約啟示錄十八章四節也被引用（但新約的連結，我們只說「使我們想起」）。','**這年有風聲傳來；那年也有風聲傳來**：原文是年復一年的風聲，意思是：不安的消息，不是一次，而是反覆。'],
exp=['四十五節，是整章的呼召，也是整個巴比倫預言的核心：我的民哪，你們要從其中出去！各人拯救自己，躲避耶和華的烈怒。這一節，和五十章八節、五十一章六節，是同一個呼召的第三次出現。三次的重複，說明了一件事：這是神最掛心的事。審判之中，神最在意的，是祂的百姓，不要陷在裡面。','四十六節，是一句很實際的安慰：你們不要心驚膽怯，也不要因境內所聽見的風聲懼怕；因為這年有風聲傳來；那年也有風聲傳來，境內有強暴的事，官長攻擊官長。這句話，對生活在不安全消息裡的人，非常真實。每一年，都有風聲；每一年，都有強暴的事。神說：不要懼怕。','四十八節，說：那時，天地和其中所有的，必因巴比倫歡呼，因為行毀滅的要從北方來到她那裡。四十九節，說：巴比倫怎樣使以色列被殺的人仆倒，照樣她全地被殺的人也必在巴比倫仆倒。這裡，有一個對應的原則。五十節，是整段的結尾：你們躲避刀劍的要快走，不要站住！要在遠方記念耶和華，心中追想耶路撒冷。請你注意：快走，也要記念。人在逃離的路上，不要忘記，心的方向。我們不為這些話，加上日期，也不套用到今日任何地方。']),
dict(a=51,z=58,star=2,lit=L(51,58),
key=[('辱罵','H2781','kherpah','辱罵、羞辱'),('慚愧','H3639','kelimmah','慚愧'),('聖所','H4720','miqdeshei','聖所'),('唉哼','H602','yeenoq','唉哼、呻吟'),('報應','H1578','gemulot','報應、回報'),('長覺','H8142','shenat olam','長久的睡眠'),('勞碌','H3021','veyagu','勞碌、疲乏')],
gram=['**我們聽見辱罵就蒙羞**：五十一節的「我們」，是被擄的百姓，在說他們心中的羞愧：外邦人，竟然進了神的殿。','**施行報應的神**：原文 El gemulot，「回報的神」；「必定施行報應」，用的是同一個動詞兩次，表示一定。'],
exp=['五十一節，是百姓的哀歌：我們聽見辱罵就蒙羞，滿面慚愧，因為外邦人進入耶和華殿的聖所。這一節，是整章最個人化的聲音。不是對巴比倫的宣告，而是被擄的人，在說：我們的羞愧。神的殿，被別人進入，這是一個很深的傷。','五十二到五十四節，神的回答：日子將到，我必刑罰巴比倫雕刻的偶像，通國受傷的人必唉哼。巴比倫雖升到天上，雖使她堅固的高處更堅固，還有行毀滅的從我這裡到她那裡。有哀號的聲音從巴比倫出來；有大毀滅的響聲從迦勒底人之地發出。這是一種很有層次的描寫：偶像受罰，傷者唉哼，高處被擊破。','五十六節說：因為耶和華是施行報應的神，必定施行報應。五十七節，重複了三十九節的酒席畫面：使他們睡了長覺，永不醒起。五十八節，用城牆與城門做結論：巴比倫寬闊的城牆必全然傾倒；她高大的城門必被火焚燒。眾民所勞碌的必致虛空。這個「勞碌必致虛空」，是整章最有普遍意義的一句話：人所勞碌的，若不是為神，終究是虛空。我們不為這些話，加上日期，也不套用到今日任何地方。']),
dict(a=59,z=62,star=2,lit=L(59,62),
key=[('西萊雅','H8304','serayah','西萊雅'),('尼利亞','H5374','neriyyah','尼利亞（巴錄的父親）'),('西底家','H6667','tsidqiyyahu','西底家'),('先知','H5030','hannavi','先知'),('寫','H3789','vayyikhtov','寫'),('念','H7121','veqarata','念、宣讀'),('荒涼','H8077','shemamot','荒涼')],
gram=['**西萊雅是王宮的大臣**：原文字面是「安歇的首領」（sar menukhah），一般認為是負責安排行程與駐紮的官員；譯法不一，我們不下定論。','**要剪除，甚至連人帶牲畜沒有在這裡居住的**：這是耶利米要西萊雅，在巴比倫念出的禱告詞。'],
exp=['五十九節，是一個全新的場景，也是整卷論列國的結尾：猶大王西底家在位第四年，上巴比倫去的時候，瑪西雅的孫子、尼利亞的兒子西萊雅與王同去，先知耶利米有話吩咐他。請你留意這一個時間記號：西底家在位第四年。這是耶利米書裡，少數把預言和一個具體的、有時間的行動，連在一起的記錄。西萊雅，是尼利亞的兒子，可能是巴錄的哥哥；我們不多說。','六十節說：耶利米將一切要臨到巴比倫的災禍，就是論到巴比倫的一切話，寫在書上。這是一卷專門的書，把一切論巴比倫的話，寫在裡面。六十一、六十二節，是耶利米對西萊雅的吩咐：你到了巴比倫，務要念這書上的話；又說：耶和華啊，你曾論到這地方說：要剪除，甚至連人帶牲畜沒有在這裡居住的，必永遠荒涼。','這裡有一個很安靜的畫面：一位官員，帶著一卷書，走進巴比倫，在這個世界最大的帝國的心臟，念出一個關於它的審判。他沒有權柄，沒有軍隊，只有一卷書。這是神的僕人，面對帝國，最有力、也最安靜的方式：念出神的話。']),
dict(a=63,z=64,star=3,lit=L(63,64),
key=[('石頭','H68','even','石頭'),('拴','H7194','tiqshor','拴住、綑綁'),('扔','H7993','vehishlakhto','扔、投'),('幼發拉底河','H6578','perat','幼發拉底河'),('沉下去','H8257','tishqa','沉下去'),('興起','H6965','taqum','興起、站起來'),('困乏','H3286','veyaafu','困乏、疲倦')],
gram=['**把一塊石頭拴在書上**：這是一個象徵行動（符號行動），像耶利米書十三章的腰帶、十九章的瓶；用一個動作，說出一個預言。','**耶利米的話到此為止**：這是整卷書的結語，不是說耶利米書到此為止（還有五十二章），而是說，耶利米的「話」，到此結束；五十二章是補述。'],
exp=['六十三、六十四節，是整個論巴比倫的預言，最後的、也是最有畫面的一個動作：你念完了這書，就把一塊石頭拴在書上，扔在幼發拉底河中，說：巴比倫因耶和華所要降與她的災禍，必如此沉下去，不再興起，人民也必困乏。這是一個象徵行動。一卷書，一塊石頭，一條河，一句話。書卷沉下去，巴比倫也要沉下去。','這個行動，很安靜，也很有力。在幼發拉底河，那個帝國的生命線上，一卷書，被一塊石頭拴住，沉入水底。沒有人看見，沒有人阻止，也沒有人慶祝。可是，這個動作，是神的話的宣告：這個看起來永不動搖的帝國，會像這卷書一樣沉下去。我們不為這個動作，加上日期，也不把它套用到今日任何地方，只讀神的僕人，怎樣把一個預言，交在神的手中。','最後一句：耶利米的話到此為止。這是一個很重的句子。論列國，論巴比倫，一路讀下來，我們到了耶利米的話的盡頭。請你想想：耶利米，從年輕的時候被呼召，一生說了這麼多話，被打、被關、被丟進坑，最後，這些話，以一卷書、一塊石頭、一條河，作結。然後，下一章，是一個歷史的補述，是整卷書的尾聲。']),
]
